@layer kg.components {
  .kg-ripple-grid {
    &[data-mask="radial"] > .kg-ripple-grid__layer {
      mask-image: radial-gradient(ellipse 75% 70% at 50% 45%, #000 30%, transparent 100%);
    }

    &[data-mask="top"] > .kg-ripple-grid__layer {
      mask-image: linear-gradient(to bottom, #000 20%, transparent 95%);
    }

    &[data-mask="bottom"] > .kg-ripple-grid__layer {
      mask-image: linear-gradient(to top, #000 20%, transparent 95%);
    }

    &[data-mask="edges"] > .kg-ripple-grid__layer {
      mask-image:
        linear-gradient(to right, transparent, #000 15% 85%, transparent),
        linear-gradient(to bottom, transparent, #000 15% 85%, transparent);
      mask-composite: intersect;
    }
  }

  .kg-ripple-grid__cell::after {
    content: "";
    position: absolute;
    inset: 2px;
    border-radius: var(--kg-radius-xs);
    background: color-mix(in oklab, var(--_c) 24%, transparent);
    box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--_c) 45%, transparent);
    opacity: 0;
    transform: scale(0.6);
    animation: kg-ripple-grid-pulse var(--_interval) var(--kg-ease-out) infinite;
    animation-delay: calc(var(--_d) * var(--_interval) * 0.45);
  }

  /* A still frame: one ring frozen part way out, so the effect still reads. */
  @media (prefers-reduced-motion: reduce) {
    .kg-ripple-grid__cell::after {
      animation: none;
      transform: scale(0.9);
      opacity: max(0, 0.7 - max(var(--_d) - 0.36, 0.36 - var(--_d)) * 6);
    }
  }

  [data-kg-motion="reduce"] .kg-ripple-grid__cell::after {
    animation: none;
    transform: scale(0.9);
    opacity: max(0, 0.7 - max(var(--_d) - 0.36, 0.36 - var(--_d)) * 6);
  }

  @keyframes kg-ripple-grid-pulse {
    0% {
      opacity: 0;
      transform: scale(0.6);
    }
    6% {
      opacity: 0.75;
      transform: scale(1);
    }
    30%,
    100% {
      opacity: 0;
      transform: scale(0.85);
    }
  }
}

import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
} from "react"
import { type BackdropMask, backdropRoot, hasChildren } from "../aurora/internal/backdrop"
import { round } from "../aurora/internal/random"

export type RippleGridMask = BackdropMask

export interface RippleGridProps extends HTMLAttributes<HTMLDivElement> {
  /** Columns, 4–40. */
  columns?: number
  /** Rows, 2–24. */
  rows?: number
  /** Any CSS color for the wave. Defaults to ink. */
  color?: string
  /** Seconds between rings. */
  interval?: number
  /** Where the ripple starts, 0–1 across and down. */
  origin?: readonly [x: number, y: number]
  mask?: RippleGridMask
  children?: ReactNode
}

const MAX_CELLS = 640

/**
 * A grid of hairline cells with a ring of light rippling out from one point. Every cell runs the
 * same keyframes, delayed by its distance from the origin, so the wave is pure CSS. Server safe.
 */
export const RippleGrid = forwardRef<HTMLDivElement, RippleGridProps>(
  (
    {
      columns = 24,
      rows = 12,
      color,
      interval = 4,
      origin = [0.5, 0.5],
      mask = "radial",
      className,
      style,
      children,
      ...props
    },
    ref,
  ) => {
    const wrapper = hasChildren(children)
    let cols = Math.round(Math.min(Math.max(columns, 4), 40))
    let lines = Math.round(Math.min(Math.max(rows, 2), 24))
    while (cols * lines > MAX_CELLS) {
      cols = Math.max(4, cols - 1)
      lines = Math.max(2, lines - 1)
    }
    const [ox, oy] = origin
    const far = Math.hypot(Math.max(ox, 1 - ox) * cols, Math.max(oy, 1 - oy) * lines) || 1
    return (
      <div
        ref={ref}
        {...backdropRoot(
          "kg-ripple-grid absolute inset-0 overflow-hidden pointer-events-none data-wrapper:relative data-wrapper:inset-auto data-wrapper:isolate data-wrapper:pointer-events-auto [--_c:var(--kg-ripple-grid-color,var(--kg-ink))] [--_interval:var(--kg-ripple-grid-interval,4s)]",
          className,
          wrapper,
        )}
        data-mask={mask}
        style={
          {
            ...(color ? { "--kg-ripple-grid-color": color } : null),
            "--kg-ripple-grid-interval": `${Math.max(interval, 0.5)}s`,
            "--_cols": cols,
            "--_rows": lines,
            ...style,
          } as CSSProperties
        }
        {...props}
      >
        <div className="kg-ripple-grid__layer pointer-events-none absolute inset-0 z-0 overflow-hidden" aria-hidden="true">
          <div className="kg-ripple-grid__cells absolute -inset-px grid grid-cols-[repeat(var(--_cols),1fr)] grid-rows-[repeat(var(--_rows),1fr)]">
            {Array.from({ length: cols * lines }, (_, index) => {
              const x = (index % cols) + 0.5 - ox * cols
              const y = Math.floor(index / cols) + 0.5 - oy * lines
              return (
                <span
                  key={index}
                  className="kg-ripple-grid__cell relative border-r border-b border-[color-mix(in_oklab,var(--kg-border)_70%,transparent)]"
                  style={{ "--_d": round(Math.hypot(x, y) / far) } as CSSProperties}
                />
              )
            })}
          </div>
        </div>
        {wrapper && <div className="kg-ripple-grid__content relative z-1">{children}</div>}
      </div>
    )
  },
)

RippleGrid.displayName = "RippleGrid"
